private def bucketSequenceMatches(index: UInt, sequence: UInt): Bool =
  bucketSeq(index)(GH_GlobalParams.GH_PACKET_SEQ_BITS - 1, packetIndexBits) ===
    sequence(GH_GlobalParams.GH_PACKET_SEQ_BITS - 1, packetIndexBits)

